-- Figures live in public/q/oct23/. Ids are fixed, so running this file again updates the test instead of copying it.

-- PeaklyTest Oct 2023 · Reading & Writing · Module 1
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'PeaklyTest Oct 2023 · Reading & Writing · Module 1', 'Reading & Writing', 'Reading & Writing, Module 1 of the Oct 2023 PeaklyTest · 27 questions · 32 minutes', 32, 330, true, 'PeaklyTest Oct 2023 · Reading & Writing', 1)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('ec576868-a88d-5f26-b37b-aba7ae1c486c', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'As used in the text, what does the word “suddenly” most nearly mean?', '["Abruptly", "Repeatedly", "Voluntarily", "Tenderly"]'::jsonb, 1, 'The following text is adapted from Kenneth Grahame’s 1908 novel The Wind in the Willows. The Mole is dazed after briefly meeting a stranger while traveling with a friend.
[The] Mole stood still a moment, held in thought. As one wakened <u>suddenly</u> from a beautiful dream, who struggles to recall it, and can re-capture nothing but a dim sense of the beauty of it, the beauty! Till that, too, fades away in its turn.'),
  ('8dfc1814-e696-5a69-ad5a-68e883a103ee', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice completes the text with the most logical and precise word or phrase?', '["a disconcerting", "an acceptable", "an imperceptible", "a substantial"]'::jsonb, 2, 'Monica Lopes-Ferreira and others at Brazil’s Butantan Institute are studying the freshwater stingray species Potamotrygon rex to determine whether biological characteristics such as the rays'' age and sex have _____ effect on the toxicity of their venom—that is, to see if differences in these traits are associated with considerable variations in venom potency.'),
  ('8a95edb1-a031-5cb2-acef-aec4a99cbded', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice completes the text with the most logical and precise word or phrase?', '["supplant", "mitigate", "venerate", "satiate"]'::jsonb, 3, 'From sculptures like Miro’s Chicago by Joan Miro, found at Brunswick Plaza, to street art like Justus roe’s mural South Shore on South Exchange Avenue, Chicago offers an array of works to _____ the tastes of art lovers.'),
  ('8a63d444-5937-538a-8107-2ba3b0e95cfd', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice completes the text with the most logical and precise word or phrase?', '["orthodox", "unequivocal", "recurrent", "unclassifiable"]'::jsonb, 4, 'Writer Lydia Davis observed that while traditional literary forms, such as the novel, are recognizable as such even as they evolve, there are rarer “intergeneric” forms that might, for example, use elements of both fiction and essays to create something _____. The late-period pieces of James Tate arguably fit this description, since they straddle the line between prose and poetry.'),
  ('864cf185-ce69-5096-83ad-b30bc7d20c69', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice completes the text with the most logical and precise word or phrase?', '["exposure to", "advancement in", "dependence on", "controversy in"]'::jsonb, 5, 'Alfred Nobel intended for the Nobel Prize to be an award honoring those who have contributed “the greatest benefit to mankind.” Indeed, the work of Richard Laurence Millington Synge represented a significant _____ the field of chemistry, and in 1952 he was among those awarded the Nobel Prize in Chemistry, for “their invention of partition chromatography.”'),
  ('e8fbe40f-d223-5c07-bd2a-73a2dd35e742', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice best states the main purpose of the text?', '["To emphasize that Darius has been looking forward to an event.", "To demonstrate that Darius and Babou would prefer not to travel.", "To show that Babou affects the way Darius thinks of himself.", "To suggest that Babou and Mamou will visit Darius in the United States soon."]'::jsonb, 6, 'The following text is adapted from Adib Khorram’s 2018 novel Darius the Great Is Not Okay. Darius, a teenager from the United States, is visiting his grandparents, Babou and Mamou, in Iran. They are preparing for a holiday celebration.

I felt like a tourist. But Babou fussed with my cap a little more, even though Mamou had already gotten it settled. He looked me in the eye from time to time, like he was looking for something, and thought maybe—just maybe—I had it in me after all. Babou hummed to himself as he smoothed out my shoulder seams and rested his hands on them. “I am glad you are here to see this, Darioush-jan.” Maybe I wasn’t such a tourist.

©2018 by Adib Khorram'),
  ('7b4dec31-df0d-5547-a5f1-8e302cd7cce9', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice best describes the function of the underlined portion in the text as a whole?', '["It presents a vivid image to emphasize a claim that Bartley makes.", "It describes an event that Bartley observed at the fair.", "It expresses doubt about the truth of a claim that Bartley made.", "It indicates the degree to which Mrs. Tarpey doubts a certain event will occur."]'::jsonb, 7, 'The following text is from Lady Gregory’s 1904 play Spreading the News. Mrs. Tarpey, Bartley, and Mrs. Fallon have been buying and selling goods at the local fair.
**MRS. TARPEY:** Good morrow, Bartley Fallon; good morrow, Mrs. Fallon. Well, Bartley, you’ll find no cause for complaining to-day; they are all saying it was a good fair.
**BARTLEY:** (Raising his voice.) It was not a good fair, Mrs. Tarpey. It was a scattered sort of a fair. If we didn’t expect more, we got less. That’s the way with me always; whatever I have to sell goes down and whatever I have to buy goes up. If there’s ever any misfortune coming to this world, it’s on myself it pitches, <u>like a flock of crows on seed potatoes.</u>'),
  ('8d76be5b-6aa6-5843-826b-33b6f24e02df', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice best describes the function of the underlined sentence?', '["It challenges the widely held view that Stephen Graham Jones based ∗Mapping the Interior∗ on events in his own life.", "It asks why so many readers who don’t enjoy the horror genre have purchased ∗Mapping the Interior∗.", "It highlights the significance of the portrayal of Indigenous people in ∗Mapping the Interior∗.", "It predicts that non-Indigenous authors will include more Indigenous characters in their work."]'::jsonb, 8, 'The 2017 novella ∗Mapping the Interior∗ confirmed that Stephen Graham Jones is one of the most talented writers of horror fiction today. <u>By featuring main characters who are Blackfeet, like Jones</u> <u>himself, the novella also helped to ensure that Indigenous people have a place within the horror genre.</u> But Jones is hardly the only Indigenous voice in horror: Metis author Cherie Dimaline has also written in the genre. Her acclaimed 2019 novel ∗Empire of Wild∗ is set in a Metis community in southern Canada.'),
  ('9d4eb690-7d6f-5a64-be4d-44c43bcb7b25', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice best states the main idea of the text?', '["Robert has put great effort into getting the attention of his superior officers.", "Robert is well suited to his role in the military.", "Robert is content with his life despite having made some mistakes.", "Robert does whatever his comrades need done even if his superiors don’t order him to do so."]'::jsonb, 9, 'The following text is from Frances E. W. Harper’s 1892 novel Jola Leroy. The text describes Robert Johnson, who has recently joined the US Army.

He was daring, without being rash; prompt, but not thoughtless; firm, without being harsh. Kind and devoted to the company he drilled, he soon won the respect of his superior officers and the love of his comrades.'),
  ('b3b8430d-53e6-5f30-ae9d-d12f70ddf7aa', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'According to the text, why did the team employ a clustering algorithm?', '["The algorithm provided insight into how customers are made aware of new gyms and beauty salons.", "The algorithm gave them an objective way to identify neighborhoods.", "The algorithm could be used to evaluate the reasons for a business’s closing.", "The algorithm could predict which types of businesses would be successful in a given neighborhood."]'::jsonb, 10, 'Researchers César A. Hidalgo, Elisa Castañer, and Andres Sevtsuk created a computer model to predict the mix of gyms, beauty salons, and other businesses found in a given neighborhood. How we define a neighborhood and its boundaries is subjective, so the team used a clustering algorithm to locate dense groupings of amenities that represent human-identified neighborhoods like Boston’s Central Square. The predictive model, which incorporates this algorithm, is sure to be invaluable in determining the optimal mix of a city’s amenities.'),
  ('e3d52511-e9e0-500e-80ec-9a5486e7ff39', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice most effectively uses data from the table to complete the text?', '["60 meters tall.", "47 meters tall.", "33 meters tall.", "40 meters tall."]'::jsonb, 11, '**Pyramids in Egypt and the Americas**

| Pyramid | Country | Height (meters) | Age (years before present) |
| The Great Pyramid | Mexico | 33 | 2,050 to 2,400 |
| The Pyramid of Djoser | Egypt | 60 | 4,600 to 4,700 |
| The Pyramid of Sahure | Egypt | 47 | 4,400 to 4,500 |
| El Castillo | Belize | 40 | 1,100 to 1,400 |

A student is writing an essay about four pyramids for a history class and wants to note how long ago each pyramid was built and how tall each pyramid is. Consulting the table, the student finds that the Pyramid of Djoser was built 4,600 to 4,700 years ago and is _____'),
  ('43f42d1f-f3b9-53c7-9c86-6b36659120cc', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which quotation from an art history textbook would most effectively support the student’s claim?', '["“Mère Poussepin has been analyzed extensively since it was first exhibited, as no two viewers seem to agree about exactly what the painting means.”", "“Of all John’s paintings, none so clearly represents her abilities and ideas as Mère Poussepin.”", "“The paintings that John produced before Mère Poussepin can be thought of as belonging to her earlier style, to which she never returned.”", "“Although John was clearly influenced by other artists of her time, she was also an artist ahead of her time, as Mère Poussepin demonstrates.”"]'::jsonb, 12, 'In a paper for an art history class, a student claims that Gwen John’s circa 1915 painting Mère Poussepin marks a significant change in John’s artistic development.'),
  ('32400999-1acf-51e5-b684-ec9b8efe84c7', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice most effectively uses data from the table to complete the assertion?', '["the average female wing centroid size was consistently larger than the average male wing centroid size in all four months in the table.", "the average male wing centroid size was larger in July than in October.", "the average female wing centroid size was 2.02 mm in July but was 2.27 mm in September.", "the average monthly low temperature was higher in September than in May."]'::jsonb, 13, '**Monthly Temperatures and Wing Centroid Sizes of Fruit Fly Specimens**

| Month | Average high (°F) | Average low (°F) | Average male wing centroid size(mm) | Average female wing centroid size(mm) |
| October | 67 | 44 | 1.98 | 2.29 |
| May | 73 | 50 | 1.98 | 2.27 |
| July | 87 | 62 | 2.02 | 2.31 |
| September | 80 | 54 | 1.98 | 2.27 |

Drosophila (fruit flies) have generation times of 10-12 days, so seasonal changes in humidity and other environmental conditions can drive seasonal fluctuations in chromosome rearrangements in species such as D. persimilis and D. subobscura. Drosophila body size (for which wing centroid size serves as a proxy measure) correlates with life span. Banu Sebnem Önder and Cansu Fidan Aksoy measured the wing sizes of members of a D. melanogaster population in Yeşilöz, Turkey, that were collected monthly between May and October over three years. Their research suggests that Drosophila collected in relatively warmer months should tend to have a longer life span, as is illustrated by the finding that _____'),
  ('b38546d2-ed00-53ab-a204-8c83bfbb0bca', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice most logically completes the text?', '["people who emigrate from north China tend to settle in Flushing, while people who emigrate from south China tend to settle in Chinatown.", "Chinese immigrants regularly change their residences between Queens and Manhattan after they emigrate, rather than staying in one borough.", "Chinese immigrants who emigrated to New York City many years ago are more likely to speak several Chinese languages than are more recent Chinese immigrants.", "taken together, there are more Cantonese and Fuzhounese speakers among Chinese immigrants in New York than there are Mandarin speakers."]'::jsonb, 14, 'Over 600 languages are spoken in New York City in addition to English—one can find Acehnese spoken in the neighborhood of Astoria, or Ilocano in Woodside. Most speakers of Chinese languages reside in the neighborhood of Flushing (part of New York City’s borough of Queens), where the dominant Chinese language is Mandarin, and in Chinatown, in the borough of Manhattan, where the dominant Chinese languages are Cantonese and Fuzhounese. Mandarin is widely spoken in north China, while Cantonese and Fuzhounese are widely spoken in south China. It can therefore be inferred that _____'),
  ('f4b548d8-1947-5edd-91da-1b5e30e56a40', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice most logically completes the text?', '["both the Llanarmon-yn-Iâl hoard and the Horsehope Craig hoard, only the latter included evidence of more refined sword production.", "hoards discovered before 1865, no such evidence was found in hoards that were discovered later.", "the Llanarmon-yn-Iâl hoard, no intact swords were found among the items in the hoard.", "the Horsehope Craig hoard, no such evidence was found in the Llanarmon-yn-Iâl hoard."]'::jsonb, 15, 'The Bronze Age in Britain lasted from around 2500 BCE to approximately 700 BCE. Collections of metal items (called hoards) from all periods of the Bronze Age have been found in Britain, including the Llanarmon-yn-Iâl hoard of artifacts from the 16th century BCE, unearthed around 1982, and the much later Horsehope Craig hoard of artifacts from the 7th century BCE, unearthed around 1865. Sometime in the Middle Bronze Age (approximately from the 14th century BCE to the 10th century BCE), metalsmiths in Britain began to develop swords for the first time. This fact helps explain why, whereas evidence of sword production was found in _____'),
  ('c8184b8b-3a22-5c29-a163-8fb204c6af2d', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["the city of Riga contains an impressive 35 percent of Latvia’s total population.", "contained within the city of Riga an impressive 35 percent of Latvia’s total population.", "of Latvia’s total population, an impressive 35 percent is contained in the city of Riga.", "an impressive 35 percent of Latvia’s total population is contained within the city of Riga."]'::jsonb, 16, 'Home to roughly 710,000 people, _____'),
  ('3ae29d44-1dae-586b-9b9f-1451bd5bc93b', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["to use", "using", "used", "use"]'::jsonb, 17, 'The size of bird eggs varies widely across species, and the researchers, _____ computer imaging to compare the lengths of eggs from species like Buteo albicaudatus and Treron vernans, aimed to shed light on the evolutionary basis for such variation.'),
  ('b48a6900-b9e2-5ae4-a84f-50748f44ea19', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["1950s, and", "1950s", "1950s,", "1950s and"]'::jsonb, 18, 'Featuring works by the photographers Liselotte Grschebina and Else “Yva” Neuländer-Simon, the 2021 exhibition The New Woman Behind the Camera set out to provide a wide-ranging overview of photography by women in the 1920s through the _____ given the collection’s breadth of more than 120 photos, its efforts were largely successful.'),
  ('1ecbd441-c328-5fde-9d77-1c176d96d92b', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["species", "species;", "species:", "species,"]'::jsonb, 19, 'In their 2019 study of butterfly diversity at Rupa Lake in Nepal, researcher Bandana Subedi and her colleagues counted 1,535 butterflies from 138 different species, including one specimen of the ______ Doleschallia bisaltide, a very rare butterfly known among lepidopterists as the autumn leaf.'),
  ('12ff0c13-285e-577f-907f-e99ccce7651f', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["lists;", "lists in", "lists. In", "lists:"]'::jsonb, 20, 'Sei Shōnagon composed many _____ “Things That Have Lost Their Power," which appears in her tenth-century account of Japanese courtly life, Pillow Book, she bemoans boats run aground, toppled trees, and defeated wrestlers.'),
  ('bdd35461-0cb4-53eb-b785-ead5d0aa26f0', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["they", "that", "it", "this"]'::jsonb, 21, 'When _____ debuted in January 1983 as part of the exhibit Women of Clay, the artworks brought vibrant visual texture to the bustling terminals of San Francisco International Airport.'),
  ('e3e5a76f-9871-5d8f-97be-e475bc2ef366', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice completes the text with the most logical transition?', '["Actually,", "For example,", "Therefore,", "Finally,"]'::jsonb, 22, 'One might assume that Germany’s Amrumbank West offshore wind farm produces the same amount of energy as land-based wind farms of a similar size. _____ because wind speeds over open water are generally higher than those over land, Amrumbank West’s turbines turn faster and produce more energy than do most land farms'' turbines.'),
  ('cc0d2400-2deb-57aa-a88c-1fbf8ae4df8a', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice completes the text with the most logical transition?', '["As a result,", "On the other hand,", "Simultaneously,", "Indeed,"]'::jsonb, 23, 'Those who looked up at the right time on July 9, 1926, would have witnessed an annular solar eclipse, during which the Moon blocks most of the Sun and causes it to look like a ring of light. _____ stargazers, on December 24, 1927, would have seen a partial solar eclipse, during which the Moon only blocks a portion of the Sun and causes it to look like a crescent.'),
  ('799e4797-be4a-59a5-a515-f85e59f32095', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice completes the text with the most logical transition?', '["Consequently,", "However,", "Lastly,", "Granted,"]'::jsonb, 24, 'For several centuries after the birth of opera in sixteenth-century Florence, Italian remained the default language in which most opera scores were written. _____ opera singers today, such as the mezzo soprano J''Nai Bridges, encounter a wide range of Italian terms—from con amore (with love) to moderato (at a moderate tempo)—when following many eighteenth-century opera scores.'),
  ('66b0db63-d781-5470-b9f8-eff037f49b81', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice most effectively uses information from the given sentences to emphasize a similarity between the two movies?', '["The Dungeon (1922) was directed by Oscar Micheaux, and The Fighting Ranger (1925) was made by Jay Marchant.", "Archives such as the Pacific Film Archive in Berkeley, California, play an integral part in preserving some of the surviving silent films from the 1920s.", "Jay Marchant’s 1925 film The Fighting Ranger is now considered lost, meaning no copies are known to exist.", "The Dungeon (1922) and The Fighting Ranger (1925) would be valuable historical documents of the era, but sadly both silent films are lost."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

Silent films can be valuable historical documents of their time.
Ninety percent of silent films made before 1930 are now lost.
A film is considered lost when no remaining copies are known to exist.
Director Oscar Micheaux’s 1922 silent film The Dungeon is lost.
Director Jay Marchant’s 1925 silent film The Fighting Ranger is lost.
Archives such as the Pacific Film Archive in Berkeley, California, help preserve some of the remaining films from the 1920s.'),
  ('6e2312dd-3cd8-5e63-a74e-5a8437f7e5fd', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'Which choice most effectively uses information from the given sentences to explain the relationship between ITUC-Africa and the BFTU?', '["ITUC-Africa is a regional union federation.", "The BFTU is one of the national union federations represented by ITUC-Africa.", "National union federations, such as the BFTU, work to improve conditions for workers in their member nations.", "The BFTU is a national union federation."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

The Botswana Federation of Trade Unions (BFTU) is a national union federation for the African nation of Botswana.
It helps improve conditions for workers in that nation.
ITUC-Africa is a regional union federation that represents national union federations across Africa. It represents the BFTU.'),
  ('33d80d38-2bc5-558c-8a9c-9ae8492bb30f', 'ce92ec4a-65fe-5bde-a880-b119ed6dc585', 'The student wants to contrast the two NWRs. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["While the James River NWR is in Virginia, on the Atlantic coast, the Hopper Mountain NWR is in California, on the Pacific coast.", "The US has designated more than 500 areas NWRs, including the James River NWR in Virginia.", "Both the James River NWR and the Hopper Mountain NWR were established to protect endangered species.", "Some NWRs were established specifically to protect endangered species such as the California condor."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

The United States has designated more than 500 areas National Wildlife Refuges (NWRs). Some NWRs were established specifically to protect endangered species.
The James River NWR is a 4,147-acre area in Virginia, on the Atlantic coast.
It was established to protect the endangered bald eagle.
The Hopper Mountain NWR is a 2,471-acre area in California, on the Pacific coast.
It was established to protect the endangered California condor.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('ec576868-a88d-5f26-b37b-aba7ae1c486c', 0, null, '**Choice A is correct.** In the sentence the narrator compares being awakened from a dream to the Mole’s state: the dream ends quickly and unexpectedly. "Suddenly" therefore means something like "abruptly" or "all at once," which matches choice A.
**Choice B is incorrect.** "Repeatedly" would imply the action happens many times, but the context describes a single, immediate awakening, not repetition.
**Choice C is incorrect.** "Voluntarily" means done by choice; here the awakening is involuntary and unexpected, so that meaning does not fit.
**Choice D is incorrect.** "Tenderly" conveys gentleness or affection, which is not suggested by the abrupt, startling sense of the awakening in the passage.
**Faster approach:** For words in context, substitute each choice into the sentence; the one that preserves the original meaning and tone (here, an abrupt awakening) is correct.'),
  ('8dfc1814-e696-5a69-ad5a-68e883a103ee', 3, null, '**Choice D is correct.** The sentence explains that researchers want to know whether age and sex are linked to “considerable variations in venom potency,” so the blank should mean a large or important effect; “a substantial” precisely conveys that meaning and matches the clarifying clause that follows.
**Choice A is incorrect.** “A disconcerting” means upsetting or alarming, which does not match the neutral, magnitude-focused explanation about variation in potency.
**Choice B is incorrect.** “An acceptable” suggests adequacy or approval, which is unrelated to the intended idea of the effect’s size.
**Choice C is incorrect.** “An imperceptible” means too small to notice, directly contradicting the parenthetical clarification that the researchers are looking for considerable variation.
**Faster approach:** Match the blank to the clarification phrase that follows; here the phrase “considerable variations” signals a synonym like “substantial,” so choose the answer with that meaning.'),
  ('8a95edb1-a031-5cb2-acef-aec4a99cbded', 3, null, '**Choice D is correct.** The sentence describes Chicago offering many different works of art, and the phrase "to _____ the tastes of art lovers" calls for a verb meaning "to satisfy" or "to fulfill" those tastes. "Satiate" precisely means to satisfy fully, so it fits both meaning and construction.
**Choice A is incorrect.** "Supplant" means "to replace," which does not make sense here—art works don’t replace tastes; they appeal to or satisfy them.
**Choice B is incorrect.** "Mitigate" means "to make less severe," which is irrelevant to the relationship between artworks and art lovers’ tastes.
**Choice C is incorrect.** "Venerate" means "to revere or worship," which would describe how people treat art but not how art relates to or fulfills tastes.
**Faster approach:** Identify the required meaning from context (what the artworks do for "tastes") and eliminate choices whose definitions clearly don’t match; choose the synonym that means "satisfy."'),
  ('8a63d444-5937-538a-8107-2ba3b0e95cfd', 3, null, '**Choice D is correct.** The passage describes “intergeneric” forms that mix elements of different genres (fiction and essays) and gives an example that “straddle[s] the line between prose and poetry.” That language signals that such works resist straightforward categorization, so “unclassifiable” precisely completes the sentence.
**Choice A is incorrect.** “Orthodox” means conventional or traditional, which contradicts the idea of mixing genres to create something that does not fit standard forms.
**Choice B is incorrect.** “Unequivocal” means clear and unambiguous; the passage implies ambiguity between genres, so this word is inappropriate.
**Choice C is incorrect.** “Recurrent” means occurring repeatedly and has no relevance to the passage’s point about genre-blending and difficulty of classification.
**Faster approach:** Use context clues—words like “intergeneric,” “straddle the line,” and the example showing mixed genres point to a word meaning not easily classified; eliminate choices with opposite or unrelated meanings.'),
  ('864cf185-ce69-5096-83ad-b30bc7d20c69', 1, null, '**Choice B is correct.** The sentence describes the significance of Synge’s work relative to chemistry; the noun phrase that fits logically and grammatically is "advancement in the field of chemistry." "Advancement" conveys progress or improvement, and the preposition "in" correctly links the improvement to the field.
**Choice A is incorrect.** "Exposure to the field of chemistry" would mean introducing someone to chemistry, which does not match the intended idea that Synge’s work benefited or progressed the field itself.
**Choice C is incorrect.** "Dependence on the field of chemistry" is illogical here: Synge’s work cannot represent a dependence on the field; the sentence praises his contribution to it.
**Choice D is incorrect.** "Controversy in the field of chemistry" implies dispute or scandal, which contradicts the positive context of a Nobel Prize for an invention that provided benefit.
**Faster approach:** Focus on collocation and context—pair positive descriptors (e.g., "significant") with nouns that mean progress ("advancement") and ensure the preposition ("in") correctly connects to the field.'),
  ('e8fbe40f-d223-5c07-bd2a-73a2dd35e742', 2, null, '**Choice C is correct.** The passage focuses on how Babou’s actions and attention change Darius’s sense of himself: Babou fusses with his cap, looks at him “like he was looking for something,” and Darius shifts from feeling like a tourist to thinking “Maybe I wasn’t such a tourist.” Those details show Babou affecting Darius’s self-perception.
**Choice A is incorrect.** Although an event is implied (preparing for a celebration), the main purpose is not to emphasize Darius’s anticipation; the text emphasizes his changing self-view instead.
**Choice B is incorrect.** Nothing in the passage indicates that Darius and Babou prefer not to travel; the word “tourist” refers to Darius’s feeling, not a desire about travel.
**Choice D is incorrect.** The passage gives no information suggesting Babou and Mamou will visit the United States, so this choice is unsupported.
**Faster approach:** Focus on the character-change or effect described in the final lines—identify who’s influencing whom—and eliminate any choices that introduce unsupported events or future actions.'),
  ('7b4dec31-df0d-5547-a5f1-8e302cd7cce9', 0, null, '**Choice A is correct.** The phrase "like a flock of crows on seed potatoes" is a simile that creates a vivid image comparing misfortune’s effect on Bartley to crows descending on potatoes; this image emphasizes his claim that misfortune always strikes him. The line does not add new narrative detail but reinforces his complaint with an evocative comparison.
**Choice B is incorrect.** The underlined phrase is not describing an event that actually occurred at the fair; it is a figurative comparison used to characterize how misfortune affects him, not a literal observation.
**Choice C is incorrect.** The simile does not express doubt about Bartley’s claim; rather, it strengthens his assertion by providing a forceful image.
**Choice D is incorrect.** The phrase does not indicate Mrs. Tarpey’s degree of doubt; it is part of Bartley’s speech and functions as a vivid metaphor for how misfortune affects him, not as a measure of another character’s skepticism.
**Faster approach:** Identify whether the phrase is literal or figurative; if it’s a simile or metaphor supporting a speaker’s complaint, it’s emphasizing a claim (choose A).'),
  ('8d76be5b-6aa6-5843-826b-33b6f24e02df', 2, null, '**Choice C is correct.** The underlined sentence explains that by featuring Blackfeet main characters the novella "helped to ensure that Indigenous people have a place within the horror genre," which directly emphasizes the significance of portraying Indigenous people in the book and its impact on the genre.
**Choice A is incorrect.** The sentence does not dispute or address whether the novella is based on the author’s life; it simply mentions that the characters are Blackfeet, like Jones himself, to make a point about representation.
**Choice B is incorrect.** The sentence does not ask a question about reader purchase habits or preferences; it states a consequence of the novella’s character choices.
**Choice D is incorrect.** The sentence makes no prediction about future actions by non-Indigenous authors; it comments on how this novella contributed to existing representation within the genre.
**Faster approach:** Look for key verbs and purpose phrases (e.g., "helped to ensure") to identify whether a sentence emphasizes significance, asks a question, makes a prediction, or challenges a claim—then eliminate choices that don’t match that purpose.'),
  ('9d4eb690-7d6f-5a64-be4d-44c43bcb7b25', 1, null, '**Choice B is correct.** The passage lists qualities—"daring, without being rash; prompt, but not thoughtless; firm, without being harsh," and says he "soon won the respect of his superior officers and the love of his comrades," which together show that Robert’s character and behavior make him well suited to military life and duties.
**Choice A is incorrect.** The passage does not say Robert sought attention; it describes his conduct and the respect he earned as a result, not effort to attract notice.
**Choice C is incorrect.** There is no mention of mistakes or of Robert being content despite them; the focus is on his admirable qualities and acceptance by others.
**Choice D is incorrect.** The passage says he was "devoted to the company he drilled" and loved by comrades, but it does not state he acted contrary to orders or favored comrades over superiors.
**Faster approach:** Summarize the passage in one phrase (qualities → outcome). Match that summary to the answer choices to pick the best fit.'),
  ('b3b8430d-53e6-5f30-ae9d-d12f70ddf7aa', 1, null, '**Choice B is correct.** The passage says that defining a neighborhood is subjective, "so the team used a clustering algorithm to locate dense groupings of amenities that represent human-identified
neighborhoods." That indicates the algorithm was used to identify neighborhoods in an objective, data-driven way.
**Choice A is incorrect.** The passage mentions customers or awareness of new businesses nowhere; the algorithm is described as locating groupings of amenities, not tracking customer awareness.
**Choice C is incorrect.** There is no mention of using the algorithm to investigate business closures or reasons for closing—only to identify neighborhood groupings and predict amenity mix.
**Choice D is incorrect.** Although the overall predictive model forecasts the optimal mix of amenities, the passage describes the clustering algorithm specifically as a way to locate neighborhoods, not as the tool that predicts business success.
**Faster approach:** Scan for purpose words like "so" or "in order to"—they signal why a method was used and point directly to the sentence stating the algorithm’s function (identifying neighborhoods).'),
  ('e3d52511-e9e0-500e-80ec-9a5486e7ff39', 0, null, '**Choice A is correct.** The table lists the Pyramid of Djoser in Egypt with a height of 60 meters, so the sentence should read that it "is 60 meters tall." This directly uses the numeric height given in the table for that pyramid.
**Choice B is incorrect.** Forty-seven meters is the height listed for the Pyramid of Sahure, not the Pyramid of Djoser.
**Choice C is incorrect.** Thirty-three meters is the height listed for The Great Pyramid (in Mexico), not the Pyramid of Djoser.
**Choice D is incorrect.** Forty meters is the height listed for El Castillo (in Belize), not the Pyramid of Djoser.
**Faster approach:** Locate the row with the named pyramid and read the corresponding height column; for table-based questions this direct look-up is the quickest reliable method.'),
  ('43f42d1f-f3b9-53c7-9c86-6b36659120cc', 2, null, '**Choice C is correct.** The quotation explicitly frames the works before Mère Poussepin as belonging to an "earlier style, to which she never returned," which directly supports the claim that that painting marks a significant change in John’s artistic development.
**Choice A is incorrect.** It discusses disagreement about the painting’s meaning, not a change in John’s style or development.
**Choice B is incorrect.** Saying the painting "represents her abilities and ideas" emphasizes its
representativeness or quality, but does not indicate a shift from earlier work.
**Choice D is incorrect.** Claiming John was "ahead of her time" speaks to innovation or influence, not explicitly to a change from her prior style.
**Faster approach:** Look for language indicating a break or departure (words like "earlier," "never returned," "marks a change") — those phrases directly signal a change in development.'),
  ('32400999-1acf-51e5-b684-ec9b8efe84c7', 1, null, '**Choice B is correct.** The table shows the average male wing centroid size is $2.02$ mm in July and $1.98$ mm in October; July has a higher average high temperature (87°F) than October (67°F). This comparison directly supports the assertion that flies collected in relatively warmer months tend to have larger wing sizes (and therefore longer life spans), because the male wing centroid size is larger in the warmer month.
**Choice A is incorrect.** Although the table does show that the average female wing centroid size is larger than the average male size in each listed month, that statement does not illustrate the specific claim about larger sizes in warmer months.
**Choice C is incorrect.** The numbers are wrong: the female wing centroid size in July is $2.31$ mm (not $2.02$ mm), so the comparison is inaccurate.
**Choice D is incorrect.** While the average low in September (54°F) is higher than in May (50°F), this temperature comparison alone does not demonstrate the link between warmer months and larger wing sizes.
**Faster approach:** Locate the warmest month in the table and directly compare its wing-size value to a cooler month; a single direct numeric comparison that shows a larger size in the warmer month is sufficient evidence.'),
  ('b38546d2-ed00-53ab-a204-8c83bfbb0bca', 0, null, '**Choice A is correct.** The passage states that Mandarin is the dominant Chinese language in Flushing and that Cantonese and Fuzhounese are the dominant Chinese languages in Chinatown. It also says Mandarin is widely spoken in north China while Cantonese and Fuzhounese are widely spoken in south China. The most direct inference is that immigrants from north China (who speak Mandarin) tend to settle in Flushing, while immigrants from south China (who speak Cantonese and Fuzhounese) tend to settle in Chinatown.
**Choice B is incorrect.** Nothing in the passage indicates people regularly move between boroughs; it only describes current language distributions.
**Choice C is incorrect.** The passage gives no information about length of residence or changes in language ability over time.
**Choice D is incorrect.** The passage compares which languages are dominant in neighborhoods, not the total number of speakers citywide, so it does not justify that Cantonese plus Fuzhounese outnumber Mandarin overall.
**Faster approach:** Match each neighborhood’s dominant language to the region of China where that language is common, then infer the likely origin of residents—this direct mapping eliminates unrelated options quickly.'),
  ('f4b548d8-1947-5edd-91da-1b5e30e56a40', 3, null, '**Choice D is correct.** The passage states that swords were developed in Britain sometime in the Middle Bronze Age (roughly 14th–10th centuries BCE). The Llanarmon-yn-Iâl hoard is dated to the 16th century BCE, which predates the Middle Bronze Age, while the Horsehope Craig hoard is dated to the 7th century BCE, which postdates it. Therefore evidence of sword production would be expected in the later Horsehope Craig hoard and not in the earlier Llanarmon-yn-Iâl hoard, matching Choice D.
**Choice A is incorrect.** It contradicts the chronological information: if swords first appear in the Middle Bronze Age, they would not be expected in the earlier Llanarmon-yn-Iâl hoard, so both hoards would not contain sword evidence.
**Choice B is incorrect.** It introduces an irrelevant distinction based on discovery date (before or after 1865) rather than the chronological dates of the artifacts that the passage uses to explain sword development.
**Choice C is incorrect.** It claims no intact swords were found in the Llanarmon-yn-Iâl hoard, but the passage implies an absence of sword production at that earlier time, not simply that intact swords were missing; moreover it ignores the clear comparison with the later hoard.
**Faster approach:** Compare the hoards'' calendar dates to the stated period when swords first appear; the hoard dated before that period won’t show sword evidence, and the one dated after will.'),
  ('c8184b8b-3a22-5c29-a163-8fb204c6af2d', 0, null, '**Choice A is correct.** The introductory phrase "Home to roughly 710,000 people," must modify the noun that immediately follows it; choice A supplies that noun phrase, "the city of Riga," and yields a complete, grammatical sentence: "Home to roughly 710,000 people, the city of Riga contains an impressive 35 percent of Latvia’s total population."
**Choice B is incorrect.** "Contained within the city of Riga an impressive 35 percent..." creates an ungrammatical construction and does not place a clear noun directly after the introductory phrase.
**Choice C is incorrect.** Beginning with "Of Latvia’s total population..." means the introductory modifier would attach to that prepositional phrase, producing a dangling modifier because it does not immediately modify a proper noun following the introductory clause.
**Choice D is incorrect.** This choice makes "an impressive 35 percent..." the subject modified by the introductory phrase, creating a dangling modifier; the intended subject (the city of Riga) must immediately follow the introductory phrase.
**Faster approach:** Place the noun being described immediately after the introductory phrase; pick the answer that begins with that noun phrase (here, "the city of Riga").'),
  ('3ae29d44-1dae-586b-9b9f-1451bd5bc93b', 1, null, '**Choice B is correct.** The sentence requires a participial phrase that modifies "the researchers" and explains how they compared egg lengths. The present-participial form "using" correctly creates a nonessential participial phrase set off by commas: "the researchers, using computer imaging to compare..., aimed to shed light..." This construction is grammatically parallel and clearly links the action to the researchers.
**Choice A is incorrect.** "to use" would create an infinitive phrase that doesn’t fit smoothly as a parenthetical modifier; it would suggest purpose rather than describe the researchers'' ongoing method and would be awkward with the commas.
**Choice C is incorrect.** "used" is a past-tense verb that would require a different clause structure (for example, "the researchers used computer imaging"), not a parenthetical participial phrase.
**Choice D is incorrect.** "use" (bare infinitive) is ungrammatical here; it cannot form the necessary participial modifier and does not fit the comma-delimited clause.
**Faster approach:** Recognize that a comma-delimited phrase describing how the researchers acted should use the present-participial "-ing" form, so choose "using."'),
  ('b48a6900-b9e2-5ae4-a84f-50748f44ea19', 0, null, '**Choice A is correct.** The sentence pairs a dependent clause beginning with "Featuring..." with an independent clause that follows the comma; to join them correctly you need a coordinating conjunction after the comma that links the two independent-structure ideas. "1950s, and" provides the decade plus the coordinating conjunction "and," correctly signaling that the second clause ("given the collection’s breadth ... its efforts were largely successful") is an independent clause conjoined to the first idea; punctuation (a comma before "and") is also required because two clauses are being joined.
**Choice B is incorrect.** "1950s" alone leaves the clauses separated by only a comma (comma splice) with no coordinating conjunction to join two independent ideas, which violates standard grammar.
**Choice C is incorrect.** "1950s," places only a comma where a coordinating conjunction is required to join the independent clause that follows; this creates a comma splice.
**Choice D is incorrect.** "1950s and" lacks the comma before the conjunction; when joining two clauses, Standard English requires a comma before the coordinating conjunction, so the punctuation is incorrect.
**Faster approach:** When a sentence has two clauses that could each stand alone, look for whether a coordinating conjunction (for, and, nor, but, or, yet, so) is present; if one is present, ensure there’s a comma before it; if it’s missing, add it. This single check quickly identifies comma splices versus correctly joined clauses.'),
  ('1ecbd441-c328-5fde-9d77-1c176d96d92b', 0, null, '**Choice A is correct.** The sentence requires no punctuation between the noun "species" and the proper name that identifies that species: "the species Doleschallia bisaltide." The phrase that follows the scientific name—"a very rare butterfly known among lepidopterists as the autumn leaf"—is an appositive set off by commas from the rest of the sentence, so the immediate boundary before the name should be blank (no additional punctuation).
**Choice B is incorrect.** A semicolon would create an inappropriate break between the general term "species" and the specific name that follows; semicolons separate independent clauses or complex list items, not a noun and the name that identifies it.
**Choice C is incorrect.** A colon would be used to introduce a list or an explanation, but here the scientific name functions as a direct noun modifier and should follow without a colon.
**Choice D is incorrect.** A comma would incorrectly separate "species" from the name it specifies; that separation is not called for because the name directly completes the noun phrase.
**Faster approach:** When a general noun is immediately followed by the specific name that identifies it (e.g., "the species X" or "the city Y"), choose no punctuation; eliminate choices that insert semicolons, colons, or commas.'),
  ('12ff0c13-285e-577f-907f-e99ccce7651f', 2, null, '**Choice C is correct.** The passage needs to be split into two sentences so that the clause beginning with "In ''Things That Have Lost Their Power,''" can be a dependent phrase modifying the rest of the second sentence. "lists. In" produces two grammatically complete sentences: "Sei Shōnagon composed many lists." and "In ''Things That Have Lost Their Power,'' which appears in her tenth-century account of Japanese courtly life, Pillow Book, she bemoans boats run aground, toppled trees, and defeated wrestlers."
**Choice A is incorrect.** "lists;" would leave the sentence a run-on because a semicolon does not appropriately separate the following introductory phrase and the independent clause that follows.
**Choice B is incorrect.** "lists in" produces a single sentence that becomes a run-on or comma splice when followed by the rest of the clause; it does not properly separate the ideas.
**Choice D is incorrect.** "lists:" would create a colon expecting a list or explanation to follow immediately; instead the next phrase is a quoted title and a clause, so a colon is inappropriate.
**Faster approach:** Look for where an independent clause must end; if the words that follow begin a new introductory phrase ("In ..."), end the first sentence with a period and capitalize the next word.'),
  ('bdd35461-0cb4-53eb-b785-ead5d0aa26f0', 0, null, '**Choice A is correct.** The sentence describes artworks that debuted in January 1983 and then states that the artworks brought texture to the terminals, so the blank must be a plural pronoun that refers to those artworks. "They" correctly agrees in number with "the artworks" and makes the sentence clear and grammatical: "When they debuted..., the artworks brought..."
**Choice B is incorrect.** "That" is a relative or demonstrative pronoun generally used for singular nouns or restrictive clauses; it does not fit the needed plural reference to "the artworks."
**Choice C is incorrect.** "It" is singular, so it does not agree with the plural noun "artworks," producing a pronoun-antecedent mismatch.
**Choice D is incorrect.** "This" is singular and demonstrative, so it also fails to agree in number with the plural "artworks."
**Faster approach:** Check pronoun-antecedent agreement quickly—identify the noun being referred to ("the artworks," plural) and choose the plural pronoun "they."'),
  ('e3e5a76f-9871-5d8f-97be-e475bc2ef366', 0, null, '**Choice A is correct.** "Actually," signals a correction of the assumption in the first sentence and fits smoothly with the explanatory clause that follows: it indicates that, contrary to what one might assume, Amrumbank West produces more energy because offshore wind speeds are higher. The sentence reads naturally: "One might assume... . Actually, because wind speeds... , Amrumbank West’s turbines turn faster..."
**Choice B is incorrect.** "For example," would introduce an instance illustrating a general point, but the second clause gives a corrective explanation, not an example of the original assumption.
**Choice C is incorrect.** "Therefore," signals a conclusion drawn from the preceding clause; here the sentence instead contradicts the assumption, so "Therefore because..." is redundant and ungrammatical.
**Choice D is incorrect.** "Finally," signals the last point in a series and does not convey the corrective contrast needed between the assumption and the factual explanation.
**Faster approach:** Pick the transition that signals contrast/correction of the preceding idea (words like "actually," "in fact," or "however") whenever the second clause contradicts or corrects the first.'),
  ('cc0d2400-2deb-57aa-a88c-1fbf8ae4df8a', 1, null, '**Choice B is correct.** The two sentences describe different kinds of solar eclipses that occurred on different dates, so the second sentence contrasts with the first. "On the other hand," signals a contrast between the annular eclipse (a ring) and the partial eclipse (a crescent), making it the most logical transition.
**Choice A is incorrect.** "As a result," indicates causation or consequence; nothing in the second sentence follows as a consequence of the first, so this transition does not fit.
**Choice C is incorrect.** "Simultaneously," implies the events happened at the same time, but the sentences give different dates, so they were not simultaneous.
**Choice D is incorrect.** "Indeed," is used to emphasize or confirm a preceding statement; it does not introduce the contrasting information about a different kind of eclipse on a different date.
**Faster approach:** Identify whether the second sentence contrasts, adds, results from, or occurs at the same time as the first; then choose the transition that matches that relationship (here, contrast → "On the other hand").'),
  ('799e4797-be4a-59a5-a515-f85e59f32095', 0, null, '**Choice A is correct.** The first sentence establishes a historical cause: Italian was the default language for opera scores for centuries. The second sentence states a present-day consequence—opera singers encounter many Italian terms—so a causal transition like "Consequently," logically links the historical fact to its present effect.
**Choice B is incorrect.** "However," signals contrast, but the second sentence does not contradict the claim about Italian being the default; it follows naturally from it, so a contrast is inappropriate.
**Choice C is incorrect.** "Lastly," implies a final item in a list; there is no list structure in the passage, so this transition is not logical.
**Choice D is incorrect.** "Granted," introduces a concession, which would weaken or qualify the prior statement; here the second sentence affirms a consequence rather than conceding anything, so "Granted," is not appropriate.
**Faster approach:** Identify whether the second sentence presents a cause, effect, contrast, or list item relative to the first; then pick the transition word that matches that relationship (here, effect → "Consequently").'),
  ('66b0db63-d781-5470-b9f8-eff037f49b81', 3, null, '**Choice D is correct.** It explicitly links the two films by stating a shared quality: both would be valuable historical documents and both are lost. The sentence synthesizes the notes that silent films can be valuable historical documents, that a film is considered lost when no copies are known to exist, and that both The Dungeon (1922) and The Fighting Ranger (1925) are lost.
**Choice A is incorrect.** It contrasts the two films by naming different directors rather than emphasizing a similarity between them.
**Choice B is incorrect.** It discusses archives preserving some films but does not compare or link the two specific movies.
**Choice C is incorrect.** It restates that The Fighting Ranger is lost but mentions only one film, so it fails to emphasize a similarity between the two films.
**Faster approach:** Scan choices for the one that mentions both films and then check whether it asserts a common attribute (e.g., both are lost); that choice will usually be the best for questions asking for a similarity.'),
  ('6e2312dd-3cd8-5e63-a74e-5a8437f7e5fd', 1, null, '**Choice B is correct.** The notes state that ITUC-Africa "represents national union federations across Africa" and that ITUC-Africa "represents the BFTU," so the clearest way to express the relationship is that the BFTU is one of the national union federations represented by ITUC-Africa.
**Choice A is incorrect.** While true, this choice only names ITUC-Africa’s type and does not explain its relationship to the BFTU.
**Choice C is incorrect.** This describes what national union federations do but does not state how ITUC-Africa and the BFTU are related to one another.
**Choice D is incorrect.** Although true, this merely identifies the BFTU’s type and fails to explain its connection to ITUC-Africa.
**Faster approach:** Look for a choice that links the two entities explicitly; eliminate options that only define one entity without describing their relationship.'),
  ('33d80d38-2bc5-558c-8a9c-9ae8492bb30f', 0, null, '**Choice A is correct.** It directly contrasts the two refuges by naming their different states and coasts, using relevant facts from the notes (James River: Virginia, Atlantic coast; Hopper Mountain: California, Pacific coast).
**Choice B is incorrect.** It states a general fact about the number of NWRs and mentions James River, but it does not compare or contrast the two specific refuges.
**Choice C is incorrect.** Although true (both were established to protect endangered species), this choice emphasizes similarity rather than contrasting the two refuges.
**Choice D is incorrect.** It gives an example of an endangered species protected by some NWRs but mentions only Hopper Mountain’s species and does not compare the two refuges.
**Faster approach:** For a contrast question, look for the answer that highlights differences (locations, protected species, sizes) rather than similarities or general facts.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

-- PeaklyTest Oct 2023 · Reading & Writing · Module 2
